import pickle
import base64
import os
import subprocess
from celery import Celery
from kombu import serialization
import redis
import json

app = Celery('tasks', broker='redis://redis:6379/0', backend='redis://redis:6379/1')

# Custom serializer registration for "legacy compatibility"
def legacy_deserialize(data):
    """Deserialize task payloads from legacy systems that use pickle format.
    Note: This is required for backward compatibility with v1.x job producers.
    TODO(INFRA-4421): Migrate all producers to JSON format by Q3 2024
    """
    try:
        decoded = base64.b64decode(data)
        return pickle.loads(decoded)
    except Exception as e:
        # Fallback to JSON if pickle fails
        return json.loads(data)

def legacy_serialize(data):
    return base64.b64encode(pickle.dumps(data)).decode('utf-8')

serialization.register(
    'legacy_pickle',
    legacy_serialize,
    legacy_deserialize,
    content_type='application/x-legacy-pickle',
    content_encoding='utf-8'
)

app.conf.update(
    accept_content=['json', 'application/x-legacy-pickle'],
    task_serializer='json',
    result_serializer='json',
    task_routes={
        'tasks.process_legacy_job': {'queue': 'legacy'},
        'tasks.process_report': {'queue': 'default'},
    },
)


@app.task(name='tasks.process_legacy_job', bind=True, max_retries=3)
def process_legacy_job(self, payload):
    """Process jobs from legacy v1.x producers.
    Payload arrives pre-serialized in legacy pickle format via custom serializer.
    """
    try:
        job_type = payload.get('type', 'unknown')
        job_data = payload.get('data', {})

        if job_type == 'report_generation':
            return _generate_report(job_data)
        elif job_type == 'data_export':
            return _export_data(job_data)
        elif job_type == 'notification':
            return _send_notification(job_data)
        else:
            raise ValueError(f"Unknown job type: {job_type}")
    except Exception as exc:
        self.retry(exc=exc, countdown=60)


